import spec from "@/generated/openapi.json";

// GET /api/v1/openapi.json   the OpenAPI 3.1 spec for every Hack OS route
// (generated by `npm run docs:api`; rendered at /api/docs). Public: no TestMu key.

export function GET() {
  return Response.json(spec, { headers: { "cache-control": "public, max-age=300" } });
}
